  function mapCodeValue(value){const n=parseInt(String(value||'0'),16);return Number.isFinite(n)?n:0}
  function mapFieldMeaning(label,value,uwp){const code=String(value||'').trim().toUpperCase(),n=mapCodeValue(code),starports={A:'Excelente: servicios completos, astillero y combustible refinado.',B:'Bueno: servicios amplios y combustible refinado; puede tener astillero.',C:'Rutinario: servicios básicos y combustible refinado.',D:'Deficiente: servicios limitados y combustible no refinado.',E:'Puesto fronterizo: instalaciones mínimas.',X:'Sin puerto estelar operativo.'},atmospheres=['Sin atmósfera; se necesita traje espacial.','Trazas; se necesita traje espacial.','Muy tenue y contaminada; requiere respirador y filtro.','Muy tenue; requiere respirador.','Tenue y contaminada; requiere filtro.','Tenue, normalmente respirable.','Estándar, respirable para humanos.','Estándar y contaminada; requiere filtro.','Densa, normalmente respirable.','Densa y contaminada; requiere filtro.','Exótica; requiere suministro de aire.','Corrosiva; requiere traje espacial.','Insidiosa; corroe equipos y requiere traje espacial.','Densa y de alta presión.','Tenue y de baja presión.','Atmósfera inusual; consulta las condiciones locales.'],governments=['Sin gobierno','Corporación o compañía','Democracia participativa','Oligarquía autoperpetuada','Democracia representativa','Tecnocracia feudal','Gobierno cautivo','Balcanización','Burocracia de servicio civil','Burocracia impersonal','Dictador carismático','Dictador no carismático','Oligarquía carismática','Dictadura religiosa'];if(label==='UWP')return 'Perfil Universal del Mundo: puerto, tamaño, atmósfera, hidrografía, población, gobierno, ley y tecnología, en ese orden.';if(label==='Hexágono')return 'Coordenada del mundo dentro del sector; permite localizarlo en el mapa.';if(label==='Sector')return 'Región cartográfica de la galaxia donde está situado el sistema.';if(label==='Zona')return code==='A'?'Zona ámbar: se recomienda precaución; existe un riesgo significativo.':code==='R'?'Zona roja: acceso restringido o prohibido.':code==='G'||!code?'Zona verde: sin alerta de viaje indicada.':`Código de zona ${code}; su interpretación depende de la ambientación.`;if(label==='Puerto estelar')return starports[code]||'Clase de puerto estelar; determina la calidad y disponibilidad de servicios.';if(label==='Tamaño')return `Código ${code}: diámetro aproximado de ${n===0?'800':Math.round(n*1600).toLocaleString('es-ES')} km.`;if(label==='Atmósfera')return atmospheres[n]||'Tipo de atmósfera codificado en el UWP.';if(label==='Hidrografía')return `${n===0?'0–5':`${n*10-4}–${Math.min(100,n*10+5)}`}% de la superficie cubierta por líquidos; el código A equivale aproximadamente al 96–100%.`;if(label==='Población')return ['Sin población','Unas pocas personas o una familia','Cientos','Miles','Decenas de miles','Cientos de miles','Millones','Decenas de millones','Cientos de millones','Miles de millones','Decenas de miles de millones','Cientos de miles de millones','Billones'][n]||'Escala de población codificada en base hexadecimal; cada paso multiplica aproximadamente por diez.';if(label==='Gobierno / ley'){const gov=uwp[5],law=uwp[6],govName=governments[mapCodeValue(gov)]||'Tipo de gobierno codificado';return `${govName}. Ley ${law}: cuanto mayor es el código, mayores suelen ser las restricciones; consulta la normativa local para saber qué artículos están limitados.`}if(label==='Nivel tecnológico')return `Nivel tecnológico ${n}: indica el desarrollo tecnológico general. A equivale a 10, B a 11, y así sucesivamente.`;if(label==='Bases')return `Instalaciones presentes en el sistema (${code}). Cada letra identifica un tipo de base; por ejemplo, N suele indicar naval y S exploradora.`;if(label==='Comercio')return `Códigos de clasificación comercial (${code}); describen rasgos útiles para determinar qué bienes se producen o demandan. Ag = agrícola, In = industrial, Ri = rico, Ni = no industrial, Po = pobre.`;if(label==='Alianza')return `Código de afiliación política (${code}); identifica la autoridad o facción con la que se relaciona el mundo.`;if(label==='Estrellas')return `Clasificación espectral y luminosidad de las estrellas principales del sistema (${code}).`;return 'Dato de navegación del mundo seleccionado.'}
  function renderMapDetails(system){const card=$('currentSystemCard');if(!system){card.hidden=true;return}card.hidden=false;const w=system.world||{},uwp=String(fieldValue(w,'UWP')||'');const attrs=[['UWP',uwp],['Hexágono',system.hex||fieldValue(w,'Hex')],['Sector',system.sector||fieldValue(w,'Sector')],['Bases',fieldValue(w,'Bases')],['Zona',fieldValue(w,'Zone')||'G'],['Puerto estelar',uwp[0]],['Tamaño',uwp[1]],['Atmósfera',uwp[2]],['Hidrografía',uwp[3]],['Población',uwp[4]],['Gobierno / ley',uwp.length>=7?`${uwp[5]} / ${uwp[6]}`:null],['Nivel tecnológico',uwp.length>=9?uwp[8]:null],['Comercio',fieldValue(w,'Remarks')],['Alianza',fieldValue(w,'Allegiance')],['Estrellas',fieldValue(w,'Stellar')]].filter(([,v])=>String(v||'').trim());card.innerHTML='<div class="system-card-head"><div><small>SISTEMA DE ESTA PARTIDA</small><h3></h3></div><button id="clearCurrentSystem" class="small-action subtle" type="button">QUITAR</button></div><div class="system-attributes"></div><section class="system-legend"><h4>LEYENDA DE ESTE MUNDO</h4><div class="system-legend-grid"></div></section>';card.querySelector('h3').textContent=system.name;const grid=card.querySelector('.system-attributes'),legend=card.querySelector('.system-legend-grid');if(!attrs.length)grid.innerHTML='<p>El sistema está guardado. Traveller Map no ha devuelto datos detallados para esta coincidencia.</p>';else attrs.forEach(([label,value])=>{const el=document.createElement('div');el.className='system-attribute';const small=document.createElement('small'),b=document.createElement('b');small.textContent=label;b.textContent=value;el.append(small,b);grid.append(el);const note=document.createElement('div');note.className='system-legend-item';const title=document.createElement('b'),meaning=document.createElement('p');title.textContent=`${label} · ${value}`;meaning.textContent=mapFieldMeaning(label,value,uwp);note.append(title,meaning);legend.append(note)});$('clearCurrentSystem').onclick=()=>{data.currentSystem=null;persist()}}
  function renderMapApp(){if(!$('systemSearchForm'))return;const system=data.currentSystem,frame=$('travellerMapFrame');$('systemSearch').value=system?.name||'';renderMapDetails(system);let url='https://travellermap.com/?style=terminal';if(system?.sector&&system?.hex&&Number.isFinite(Number(system.mapX))&&Number.isFinite(Number(system.mapY))){const x=Number(system.mapX),y=Number(system.mapY),params=new URLSearchParams({x:String(x),y:String(y),scale:'128',style:'terminal',yah_x:String(x),yah_y:String(y)});url=`https://travellermap.com/?${params}`}else if(system?.sector&&system?.hex){const params=new URLSearchParams({sector:system.sector,hex:system.hex,style:'terminal',yah:'1'});url=`https://travellermap.com/?${params}`;ensureMapPoint(system)}else if(system?.name){const params=new URLSearchParams({qn:system.name,style:'terminal'});url=`https://travellermap.com/?${params}`}if(frame.getAttribute('src')!==url)frame.src=url;$('openFullMap').href=url}
  function ensureMapPoint(system){const key=`${system.sector}|${system.hex}`;if(mapLocationPending===key||!system.sector||!system.hex)return;mapLocationPending=key;apiJsonp(`/api/coordinates?sector=${encodeURIComponent(system.sector)}&hex=${encodeURIComponent(system.hex)}`).then(coords=>{const wxRaw=fieldValue(coords,'X'),wyRaw=fieldValue(coords,'Y'),wx=Number(wxRaw),wy=Number(wyRaw);if(wxRaw===''||wyRaw===''||!Number.isFinite(wx)||!Number.isFinite(wy))return;const mapX=(wx-.5)*Math.cos(Math.PI/6),mapY=-(wy-(Math.abs(wx)%2===0?.5:0)),current=data.currentSystem;if(!current||current.sector!==system.sector||current.hex!==system.hex)return;current.mapX=Number(mapX.toFixed(4));current.mapY=Number(mapY.toFixed(4));persist()}).catch(()=>{}).finally(()=>{if(mapLocationPending===key)mapLocationPending=''})}
  async function searchSystem(query){const status=$('systemSearchStatus'),host=$('systemSearchResults');host.replaceChildren();status.textContent='BUSCANDO EN TRAVELLER MAP…';try{const payload=await apiJsonp(`/api/search?q=${encodeURIComponent(query)}`),results=mapResults(payload).filter(r=>r.name);if(!results.length){status.textContent='No se encontraron sistemas. Prueba con otro nombre.';return}status.textContent=`${results.length} coincidencia${results.length===1?'':'s'} · selecciona el sistema correcto`;results.slice(0,8).forEach(result=>{const button=document.createElement('button');button.type='button';button.className='system-result';const title=document.createElement('b'),meta=document.createElement('small');title.textContent=result.name;meta.textContent=[result.sector,result.hex].filter(Boolean).join(' · ')||'Coincidencia de Traveller Map';button.append(title,meta);button.onclick=()=>selectSystem(result);host.append(button)})}catch{status.textContent='No se pudo consultar el buscador. Comprueba la conexión y vuelve a intentarlo; el mapa completo sigue disponible.'}}
  async function selectSystem(result){$('systemSearchStatus').textContent='CARGANDO DATOS DEL SISTEMA…';let world=result.world||{};if(result.sector&&result.hex){try{const payload=await apiJsonp(`/api/jumpworlds?sector=${encodeURIComponent(result.sector)}&hex=${encodeURIComponent(result.hex)}&jump=0`),worlds=payload?.Worlds||payload?.worlds||payload?.Results?.Items||payload?.results||[];if(Array.isArray(worlds)&&worlds.length)world=worlds.find(w=>String(fieldValue(w,'Hex'))===String(result.hex))||worlds[0]}catch{}}const sector=result.sector||fieldValue(world,'Sector'),hex=result.hex||fieldValue(world,'Hex');data.currentSystem={name:result.name,sector,hex,world};persist();$('systemSearchResults').replaceChildren();$('systemSearchStatus').textContent='SISTEMA GUARDADO · MAPA CENTRADO EN EL MUNDO';renderMapApp()}    function renderNotes(){const host=$('notesList');host.replaceChildren();const notes=[...(data.notes||[])].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));if(!notes.length){host.innerHTML='<div class="empty-notes">Todavía no hay notas guardadas. Pulsa «Añadir nota» para crear la primera.</div>';return}notes.forEach(note=>{const card=document.createElement('button');card.type='button';card.className='note-card';card.innerHTML='<span class="note-card-glyph">✎</span><span class="note-card-title"></span><span class="note-card-arrow">→</span>';card.querySelector('.note-card-title').textContent=note.title;card.onclick=()=>openNote(note.id);host.append(card)})}
  function openNote(id=null){activeNoteId=id;const note=(data.notes||[]).find(n=>n.id===id);$('noteTitle').value=note?.title||'';$('noteBody').value=note?.body||'';$('notesList').hidden=true;$('noteEditor').hidden=false;$('addNoteButton').hidden=true;$('deleteNoteButton').hidden=!note;$('noteSaveStatus').textContent='NOTA GUARDADA EN ESTA PARTIDA';$('noteTitle').focus()}
  function saveNote(closeAfter=true){const title=$('noteTitle').value.trim(),body=$('noteBody').value;if(!title){if(!activeNoteId&&!body.trim()){if(closeAfter){$('noteEditor').hidden=true;$('notesList').hidden=false;$('addNoteButton').hidden=false;activeNoteId=null}return true}alert('Pon un título a la nota antes de guardarla.');$('noteTitle').focus();return false}const notes=data.notes||(data.notes=[]),existing=notes.find(n=>n.id===activeNoteId),now=new Date().toISOString();if(existing){existing.title=title;existing.body=body;existing.updatedAt=now}else{const note={id:crypto.randomUUID(),title,body,updatedAt:now};notes.unshift(note);activeNoteId=note.id}const campaign=store.campaigns.find(c=>c.id===activeId);if(campaign)campaign.data=data;saveLocalStore();queueCloudSave(campaign);$('noteSaveStatus').textContent='GUARDADA EN ESTA PARTIDA';if(closeAfter){$('noteEditor').hidden=true;$('notesList').hidden=false;$('addNoteButton').hidden=false;renderNotes();activeNoteId=null}return true}
  function deleteNote(){const note=(data.notes||[]).find(n=>n.id===activeNoteId);if(!note)return;if(!confirm(`¿Eliminar la nota «${note.title}»? Esta acción no se puede deshacer.`))return;data.notes=data.notes.filter(n=>n.id!==activeNoteId);const campaign=store.campaigns.find(c=>c.id===activeId);if(campaign)campaign.data=data;saveLocalStore();queueCloudSave(campaign);activeNoteId=null;$('noteEditor').hidden=true;$('notesList').hidden=false;$('addNoteButton').hidden=false;renderNotes()}
  function renderStocks(){const host=$('stockList');host.replaceChildren();Object.entries(categories).forEach(([key,name],index)=>host.append(makeStockRow(key,name,index)))}
  function renderProductOptions(){const select=$('product'),selected=select.value;for(const option of [...select.options])if(option.dataset.custom)option.remove();Object.entries(data.custom).forEach(([key,name])=>{const option=document.createElement('option');option.value=key;option.textContent=name;option.dataset.custom='true';select.append(option)});if([...select.options].some(o=>o.value===selected))select.value=selected}
  function makeStockRow(key,name,index=0){const row=document.createElement('button');row.type='button';row.className='stock-row stock-row-open';row.setAttribute('aria-label',`Abrir ${name}`);const packSize=data.inventoryDetails[key]?.packSize||1;row.innerHTML=`<span class="stock-icon ${index%2?'advanced-icon':'basic-icon'}">${index<2?'⌘':index<4?'◇':'◈'}</span><span class="stock-name"><b></b><small></small></span><b class="stock-count">${whole(data.inventory[key]||0)}</b><span class="stock-unit">uds.</span><span class="stock-menu" aria-hidden="true">›</span>`;row.querySelector('.stock-name b').textContent=name;row.querySelector('.stock-name small').textContent=`${categories[key]?'INVENTARIO':'ARTÍCULO PERSONALIZADO'} · ${whole(packSize)} UD./PACK`;row.onclick=()=>openInventoryItem(key,name);return row}
  function renderCustom(){const host=$('customStocks');host.replaceChildren();Object.entries(data.custom).forEach(([key,name])=>host.append(makeStockRow(key,name,1)))}
  function openInventoryItem(key,name){activeInventoryKey=key;$('inventoryListView').hidden=true;$('inventoryDetailView').hidden=false;$('inventoryItemName').textContent=name;$('inventoryUnits').value=data.inventory[key]||0;$('inventoryPackSize').value=data.inventoryDetails[key]?.packSize||1;$('inventoryUnitValue').value=data.inventoryDetails[key]?.unitValue||'';$('inventorySalePacks').value='1';$('inventorySaleMode').value='ordinary';$('inventorySaleRoll').value='';$('inventorySaleRollField').hidden=true;calculateInventorySale()}
  function renderInventoryDetail(){if(!activeInventoryKey||$('inventoryDetailView').hidden)return;const key=activeInventoryKey;$('inventoryItemName').textContent=productName(key);const units=Math.max(0,Math.trunc(Number($('inventoryUnits').value)||0)),size=Math.max(1,Math.trunc(Number($('inventoryPackSize').value)||1));$('inventoryUnitsAvailable').textContent=`DISPONIBLES: ${whole(units)} UDS. · ${whole(Math.floor(units/size))} PACKS COMPLETOS${units%size?` + ${whole(units%size)} SUELTAS`:''}`;const unitValue=Math.max(0,Number($('inventoryUnitValue').value)||0),packs=Math.max(0,Number($('inventorySalePacks').value)||0),roll=Number($('inventorySaleRoll').value),commercial=$('inventorySaleMode').value==='commercial',rate=commercial&&$('inventorySaleRoll').value.trim()?rowRate(roll)[2]:100,qty=packs*size;$('inventorySaleUnits').textContent=whole(qty);$('inventorySaleRate').textContent=`${fmt(rate)}%`;$('inventorySaleTotal').textContent=`${fmt(unitValue*qty*rate/100)} Cr`;$('inventorySaleAction').disabled=!unitValue||!packs||qty>units||(commercial&&!$('inventorySaleRoll').value.trim())}
  function calculateInventorySale(){renderInventoryDetail()}
  function saveInventoryDetails(){if(!activeInventoryKey)return;const units=Math.max(0,Math.trunc(Number($('inventoryUnits').value)||0)),packSize=Math.max(1,Math.trunc(Number($('inventoryPackSize').value)||1)),unitValue=Math.max(0,Number($('inventoryUnitValue').value)||0);data.inventory[activeInventoryKey]=units;data.inventoryDetails[activeInventoryKey]={packSize,unitValue};persist()}
  function askInventorySale(){if(!activeInventoryKey)return;const key=activeInventoryKey,units=Math.max(0,Math.trunc(Number($('inventoryUnits').value)||0)),packSize=Math.max(1,Math.trunc(Number($('inventoryPackSize').value)||1)),packs=Math.trunc(Number($('inventorySalePacks').value)),qty=packs*packSize,unitValue=Math.max(0,Number($('inventoryUnitValue').value)||0),commercial=$('inventorySaleMode').value==='commercial',roll=commercial?Math.trunc(Number($('inventorySaleRoll').value)):null;if(!Number.isInteger(packs)||packs<1){alert('Indica cuántos packs quieres vender.');return}if(!unitValue){alert('Indica el valor base por unidad del ítem.');return}if(qty>units){alert(`Inventario insuficiente: tienes ${units} unidades.`);return}if(commercial&&!$('inventorySaleRoll').value.trim()){alert('Introduce la tirada comercial.');return}const rate=commercial?rowRate(roll)[2]:100,total=unitValue*qty*rate/100;pendingInventorySale={key,qty,units,packSize,unitValue,roll,rate,total,commercial};$('dialogTitle').textContent='Confirmar venta de inventario';$('dialogSummary').textContent=`Vender ${whole(packs)} pack${packs===1?'':'s'} de ${productName(key)} (${whole(qty)} unidades) por ${fmt(total)} Cr · ${commercial?`venta comercial, tirada ${roll}, ${fmt(rate)}%`:'venta ordinaria, 100% del valor base'}. La cartera aumentará y el inventario disminuirá.`;$('dialogCancel').textContent='NO, CANCELAR';$('dialogConfirm').textContent='SÍ, CONFIRMAR VENTA';$('dialogConfirm').className='confirm-button sell-confirm';$('confirmDialog').showModal()}
  function saveInventorySale(){if(!pendingInventorySale)return;const sale=pendingInventorySale;pendingInventorySale=null;if((Number(data.inventory[sale.key])||0)<sale.qty){alert('El inventario ha cambiado y ya no hay unidades suficientes.');return}const balanceBefore=data.wallet;data.undo={wallet:data.wallet,inventory:structuredClone(data.inventory),inventoryDetails:structuredClone(data.inventoryDetails),ships:structuredClone(data.ships||[]),history:structuredClone(data.history)};data.wallet+=sale.total;data.inventory[sale.key]=sale.units-sale.qty;data.inventoryDetails[sale.key]={packSize:sale.packSize,unitValue:sale.unitValue};$('inventoryUnits').value=data.inventory[sale.key];data.history.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),mode:'sell',product:sale.key,qty:sale.qty,total:sale.total,roll:sale.roll,rate:sale.rate,unit:sale.unitValue*sale.rate/100,balanceBefore,note:`${sale.commercial?'Venta comercial':'Venta ordinaria'} desde inventario · ${productName(sale.key)}`});persist();pulseGreen();$('confirmDialog').close();$('inventorySalePacks').value='1';renderInventoryDetail()}
  function closeInventoryDetail(){activeInventoryKey=null;$('inventoryDetailView').hidden=true;$('inventoryListView').hidden=false}
  function calculateView(){const c=calc();$('rateLabel').textContent=c.rate===null?'—':`${fmt(c.rate)}%`;$('rateLabel').classList.toggle('active-sell-label',mode==='sell');$('totalValue').innerHTML=c.total===null?'—':`${fmt(c.total)} <i>Cr</i>`;$('quantityLabel').textContent=c.qty===null?'—':`${whole(c.qty)} ${c.qty===1?'unidad':'unidades'}`;$('unitResult').textContent=c.unit===null?'—':`${fmt(c.unit)} Cr / ud.`;$('calcNote').textContent=c.roll===null?'Introduce la tirada total':`Tirada ${c.roll} · tarifa de tabla ${fmt(c.base)}%`; $('confirmText').textContent=mode==='buy'?'CONFIRMAR COMPRA':'CONFIRMAR VENTA';$('confirmArrow').textContent=mode==='buy'?'↙':'↗';$('confirmBtn').classList.toggle('sell-confirm',mode==='sell');$('confirmBtn').classList.toggle('buy-confirm',mode==='buy');$('buyMode').className='mode'+(mode==='buy'?' active-buy':'');$('sellMode').className='mode'+(mode==='sell'?' active-sell':'')}
  function renderHistory(){
    const host=$('historyList');host.replaceChildren();const items=historyExpanded?data.history:data.history.slice(0,3);
    if(!items.length){host.innerHTML='<div class="empty-history">Sin operaciones registradas.</div>'}
    else items.forEach(tx=>{
      const node=document.createElement('article'),isCredit=tx.type==='credit',modeClass=isCredit?(tx.direction==='add'?'credit-add':'credit-remove'):tx.mode;
      node.className='history-item';node.innerHTML=`<div class="history-entry-head"><div class="history-symbol ${modeClass}">${isCredit?(tx.direction==='add'?'＋':'−'):tx.mode==='buy'?'↙':'↗'}</div><div class="history-desc"><b></b><small></small></div><div class="history-amount ${isCredit?(tx.direction==='add'?'plus':'minus'):tx.mode==='buy'?'minus':'plus'}"></div></div><div class="history-entry-meta"><span class="history-concept"><small>CONCEPTO</small><b></b></span><span class="history-balance"><small>SALDO ANTERIOR</small><b></b></span></div>`;
      node.querySelector('.history-desc b').textContent=isCredit?(tx.direction==='add'?'Cr añadidos':'Cr quitados'):`${tx.mode==='buy'?'Compra':'Venta'} · ${productName(tx.product)}`;
      node.querySelector('.history-desc small').textContent=new Date(tx.date).toLocaleString('es-ES',{dateStyle:'short',timeStyle:'short'});
      node.querySelector('.history-amount').innerHTML=`${isCredit?(tx.direction==='add'?'+':'−'):tx.mode==='buy'?'−':'+'}${fmt(isCredit?tx.amount:tx.total)} Cr<small>${isCredit?'Movimiento de cartera':tx.roll===null?`${tx.note?.includes('ordinaria')?'Venta ordinaria · ':''}${fmt(tx.rate)}%`:`Tirada ${tx.roll} · ${fmt(tx.rate)}%`}</small>`;
      node.querySelector('.history-concept b').textContent=tx.note?.trim()||'Sin concepto';
      node.querySelector('.history-balance b').textContent=Number.isFinite(tx.balanceBefore)?`${fmt(tx.balanceBefore)} Cr`:'No registrado';
      node.querySelector('.history-balance').classList.toggle('balance-unavailable',!Number.isFinite(tx.balanceBefore));host.append(node)
    });
    $('historyAll').hidden=data.history.length<=3;$('historyAll').innerHTML=historyExpanded?'MOSTRAR RECIENTES <span>↑</span>':'VER HISTORIAL COMPLETO <span>→</span>'
  }
  function pulseGreen(ids=['walletValue','itemsValue','historyList']){ids.forEach(id=>{const el=$(id);if(!el)return;el.classList.remove('terminal-pulse');void el.offsetWidth;el.classList.add('terminal-pulse');setTimeout(()=>el.classList.remove('terminal-pulse'),850)})}
